"""Create changelog fragments from the body of a pull request generated by pre-commit.ci."""

from __future__ import annotations

import os
import re
from pathlib import Path

FRAGMENTS_DIR = Path('changelog.d')

# Matches lines such as
#   - [github.com/astral-sh/ruff-pre-commit: v0.4.7 → v0.17.5](https://github.com/...)
#   - https://github.com/PyCQA/doc8/: v1.1.1 → v2.0.0
HOOK_UPDATE = re.compile(
    r'^-\s+\[?(?:https?://)?[^/\s]+/(?P<name>[^\s:]+?)(?:\.git)?/?:\s+\S+\s+→\s+[vV]?(?P<version>[^\s\]]+)'
)


def main() -> None:
    """Write one fragment per updated hook (a later update of the same hook overwrites the fragment)."""
    for line in os.environ['PR_BODY'].splitlines():
        match = HOOK_UPDATE.match(line.strip())
        if not match:
            continue
        name, version = match['name'], match['version']
        slug = re.sub(r'[^a-z0-9]+', '-', name.lower()).strip('-')
        fragment = FRAGMENTS_DIR / f'+pre-commit-{slug}.repository.md'
        fragment.write_text(f'Update `{name}` hook to v{version}\n', encoding='utf-8')
        print(f'{fragment}: {name} -> v{version}')


if __name__ == '__main__':
    main()
